def is_broken(url):
    """A URL is 'broken' for our purposes if it uses a retired scheme
    or has an empty host. Bare fragment/query anchors (e.g. "#section",
    "?q=1") have no host to validate, so they are not broken."""
    for scheme in BROKEN_SCHEMES:
        if url.startswith(scheme):
            return True
    if "://" not in url:
        return False
    host = url.split("://", 1)[1].split("/", 1)[0]
    return not host
